from openpyxl.utils import get_column_letter
from copy import copy

path = '/root/data/workbook.xlsx'
wb = load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)

def row_values(ws, row, start_col, end_col):
    return [ws.cell(row=row, column=c).value for c in range(start_col, end_col+1)]

def print_rows(ws, start_row, end_row, start_col, end_col, title):
    print('\n' + title)
    header = ['row'] + [get_column_letter(c) for c in range(start_col, end_col+1)]
    print(header)
    for r in range(start_row, end_row+1):
        print([r] + row_values(ws, r, start_col, end_col))

def print_col(ws, col, start_row, end_row, title):
    print('\n' + title)
    print(['row', get_column_letter(col)])
    for r in range(start_row, end_row+1):
        print([r, ws.cell(r, col).value])

def merged_owner(ws, row, col):
    coord = ws.cell(row, col).coordinate
    for rng in ws.merged_cells.ranges:
        if coord in rng:
            return str(rng), ws.cell(rng.min_row, rng.min_col).coordinate
    return None, coord

def fill_sig(cell):
    f = cell.fill
    if f is None:
        return None
    return {
        'type': f.fill_type,
        'fg': f.fgColor.rgb or f.fgColor.indexed or f.fgColor.theme or f.fgColor.type,
        'bg': f.bgColor.rgb or f.bgColor.indexed or f.bgColor.theme or f.bgColor.type,
    }

def print_merge_fill(ws, range_string):
    print('\nMerge/fill pattern', range_string)
    min_col = ws[range_string][0][0].column
    max_col = ws[range_string][0][-1].column
    min_row = ws[range_string][0][0].row
    max_row = ws[range_string][-1][0].row
    relevant = [str(r) for r in ws.merged_cells.ranges if not (r.max_row < min_row or r.min_row > max_row or r.max_col < min_col or r.min_col > max_col)]
    print('merged ranges intersecting:', relevant)
    print(['cell','value','merged_range','owner','fill'])
    for r in range(min_row, max_row+1):
        for c in range(min_col, max_col+1):
            cell = ws.cell(r,c)
            mr, owner = merged_owner(ws,r,c)
            print([cell.coordinate, cell.value, mr, owner, fill_sig(cell)])

task = wb['Task']
data = wb['Data']
print_rows(task, 10, 11, 1, 12, 'Task rows 10-11 A:L')
print_col(task, 4, 12, 31, 'Task column D rows 12-31 series codes')
print_rows(task, 35, 50, 1, 7, 'Task rows 35-50 columns A-G labels/structure')
for rng in ['H12:L17', 'H19:L24', 'H26:L31', 'H35:L47', 'H50:L50']:
    print_merge_fill(task, rng)
print_rows(data, 19, 40, 1, data.max_column, 'Data rows 19-40 all used columns')

# Determine likely geometry programmatically from rows 19-40.
print('\nData dimensions:', data.max_row, data.max_column)
for r in range(19, 41):
    vals = row_values(data, r, 1, data.max_column)
    nonempty = [(get_column_letter(i+1), v) for i, v in enumerate(vals) if v is not None]
    print('Nonempty row', r, nonempty)

# Find header row with years and data rows with series code-like values.
for r in range(19, 41):
    years = []
    for c in range(1, data.max_column+1):
        v = data.cell(r,c).value
        if isinstance(v, int) and 1900 <= v <= 2100:
            years.append((c, v))
        elif isinstance(v, str) and v.strip().isdigit() and 1900 <= int(v.strip()) <= 2100:
            years.append((c, v))
    if years:
        print('Candidate year header row:', r, [(get_column_letter(c), v) for c, v in years])

for c in range(1, data.max_column+1):
    vals = [data.cell(r,c).value for r in range(21,39)]
    nonempty = [v for v in vals if v is not None]
    if nonempty:
        print('Candidate data col', get_column_letter(c), 'nonempty rows21-38 sample:', nonempty[:8])
